            DataT C[SIZE][SIZE]) {
    // Partition arrays along the first dimension to allow parallel access to different rows.
    // This supports the pipelined inner loops where different iterations access different rows.
    #pragma HLS ARRAY_PARTITION variable=A dim=1 complete
    #pragma HLS ARRAY_PARTITION variable=B dim=1 complete
    #pragma HLS ARRAY_PARTITION variable=C dim=1 complete

    // Swap loop order to process columns of C sequentially, but rows in parallel.
    // This allows pipelining the i-loop without requiring column-wise partitioning.
    for (int j = 0; j < SIZE; j++) {
        for (int i = 0; i < SIZE; i++) {
            #pragma HLS PIPELINE
            DataT acc = 0;
            for (int k = 0; k < SIZE; k++) {
                #pragma HLS PIPELINE
                #pragma HLS UNROLL factor=4
                acc += A[i][k] * B[k][j];
            }
            C[i][j] = acc;
        }
    }
}

